test_that("MV17-C closure is provenance-complete and remains feasibility-only", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17c-calibration-closure-v1");skip_if_not(dir.exists(a),"MV17-C closure absent");r<-function(n)read.csv(file.path(a,n),stringsAsFactors=FALSE,check.names=FALSE);v<-r("mv17c-validation.csv");e<-r("mv17c-empirical-calibration.csv");d<-r("mv17c-decision.csv");m<-r("mv17c-artifact-manifest.csv");expect_equal(nrow(v),19L);expect_true(all(v$passed));expect_equal(nrow(e),168L);expect_true(all(e$minimum_attainable_probability==.1));expect_true(d$MV17C_closed);expect_true(d$MV17G_prefreeze_eligible);expect_false(d$full_calibration_authorized);files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);hashes<-vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE);expect_equal(unname(hashes),unname(m$sha256))
})
